 ST.panel('Where customers are on the journey','<div style="display:grid;gap:8px">'+STG.map(function(s,i){return '<div style="display:grid;grid-template-columns:190px 1fr 40px;gap:10px;align-items:center;font-size:14px"><span>'+(i+1)+'. '+s[1]+'</span><span style="background:#EEF1F4;border-radius:8px;height:18px;overflow:hidden"><i style="display:block;height:100%;width:'+Math.round(cnt[i]/mx*100)+'%;background:'+COLS[i]+'"></i></span><b>'+cnt[i]+'</b></div>'}).join('')+'</div><p style="color:var(--mute);font-size:13px;margin:10px 0 0">From the day the customer pays for assisted service (Pro pack, Premium property or comprehensive report) to the auction outcome. Concierge customers are tracked separately until the end of their term.</p>')+
 ST.panel('Customer journeys ('+L.length+')','<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px"><input id="jq" class="cs" style="color:var(--ink);min-width:200px" placeholder="Search customer or property" value="'+esc(st.q)+'"><select id="jp" class="cs" style="color:var(--ink)"><option value="">All services</option>'+PL.map(function(p){return '<option'+(st.plan===p?' selected':'')+'>'+p+'</option>'}).join('')+'</select><select id="js" class="cs" style="color:var(--ink)">'+[['','Any status'],['active','In progress'],['stuck','Stuck'],['won','Won'],['lost','Did not win'],['done','Finished']].map(function(o){return '<option value="'+o[0]+'"'+(st.s===o[0]?' selected':'')+'>'+o[1]+'</option>'}).join('')+'</select></div>'+
 ST.table(['Customer','Service and property','Progress','Now','District Sales Manager',''],L.map(function(j){return '<tr><td><b>'+esc(j.name)+'</b><br><small style="color:var(--mute)">+91 '+esc(j.phone)+'</small></td><td>'+esc(j.plan)+'<br><small style="color:var(--mute)">'+esc(j.prop)+'</small></td><td style="min-width:240px">'+trackSvg(j,false)+'</td><td>'+(j.out?ST.chip(j.out==='won'?'Won':j.out==='lost'?'Did not win':'Withdrew',j.out==='won'?'g':'n'):j.done?ST.chip('Finished','g'):ST.chip(esc(j.stage[1]),j.stuck?'r':'b'))+'<br><small style="color:var(--mute)">'+(j.stuck?'<b style="color:#A50E0E">'+Math.round(j.since/D)+' days in this stage</b>':ST.ago(j.last.at))+'</small></td><td>'+esc(j.dsmName||'—')+'<br><small style="color:var(--mute)">'+esc(j.state)+'</small></td><td><button class="btn out sm" data-j="'+j.phone+'">Open map</button></td></tr>'}),'')+'',
 '<button class="btn out sm" id="jcsv">Download CSV</button>');
 el.onclick=function(e){var b=e.target.closest('[data-j]');if(b){st.sel=b.dataset.j;re()}};
 $('jq').oninput=function(){st.q=this.value.toLowerCase();var p=this.selectionStart;re();$('jq').focus();$('jq').setSelectionRange(p,p)};$('jp').onchange=function(){st.plan=this.value;re()};$('js').onchange=function(){st.s=this.value;re()};
